const STAGES = ['待投递', '已投递', '面试中', '已结束'];
const STORE_KEY = 'jobApplications';

const el = (sel) => app.querySelector(sel);
const fields = {
  company: el('[data-field="company"]'),
  position: el('[data-field="position"]'),
  date: el('[data-field="date"]'),
  stage: el('[data-field="stage"]'),
  note: el('[data-field="note"]')
};
const formTitle = el('#form-title');
const formMode = el('[data-role="form-mode"]');
const formError = el('[data-role="form-error"]');
const listError = el('[data-role="list-error"]');
const listEl = el('[data-role="list"]');
const emptyEl = el('[data-role="empty"]');
const listCount = el('[data-role="list-count"]');
const resetBtn = el('[data-action="reset"]');
const confirmBox = el('[data-role="confirm-box"]');
const confirmText = el('[data-role="confirm-text"]');
const confirmDeleteBtn = el('[data-action="confirm-delete"]');
const cancelDeleteBtn = el('[data-action="cancel-delete"]');
const chipButtons = Array.from(app.querySelectorAll('.chip'));

let state = null;
let filter = '全部';
let editingId = null;
let pendingDeleteId = null;

function todayStr() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${m}-${day}`;
}

function seedRecords() {
  const t = todayStr();
  return [
    { id: 'seed-1', company: '星辰科技', position: '前端开发工程师', date: t, stage: '已投递', note: '官网投递，等待 HR 回复。' },
    { id: 'seed-2', company: '云图数据', position: 'Web 前端实习生', date: t, stage: '面试中', note: '一面已通过，二面约在下周三下午。' },
    { id: 'seed-3', company: '海蓝网络', position: '前端工程师', date: t, stage: '待投递', note: '需要准备作品集链接。' }
  ];
}

function normalizeRecord(raw) {
  const r = (raw && typeof raw === 'object') ? raw : {};
  const stage = STAGES.includes(r.stage) ? r.stage : '待投递';
  return {
    ...r,
    id: typeof r.id === 'string' && r.id ? r.id : `rec-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    company: typeof r.company === 'string' ? r.company : '',
    position: typeof r.position === 'string' ? r.position : '',
    date: typeof r.date === 'string' ? r.date : '',
    stage,
    note: typeof r.note === 'string' ? r.note : ''
  };
}

function normalizeState(raw) {
  const s = (raw && typeof raw === 'object') ? raw : {};
  const list = Array.isArray(s[STORE_KEY]) ? s[STORE_KEY].map(normalizeRecord) : null;
  return { ...s, [STORE_KEY]: list };
}

function showError(node, msg) {
  node.textContent = msg;
  node.hidden = false;
}

function clearError(node) {
  node.textContent = '';
  node.hidden = true;
}

function readForm() {
  return {
    company: fields.company.value.trim(),
    position: fields.position.value.trim(),
    date: fields.date.value,
    stage: STAGES.includes(fields.stage.value) ? fields.stage.value : '待投递',
    note: fields.note.value.trim()
  };
}

function fillForm(record) {
  fields.company.value = record.company || '';
  fields.position.value = record.position || '';
  fields.date.value = record.date || '';
  fields.stage.value = STAGES.includes(record.stage) ? record.stage : '待投递';
  fields.note.value = record.note || '';
}

function clearForm() {
  fields.company.value = '';
  fields.position.value = '';
  fields.date.value = todayStr();
  fields.stage.value = '待投递';
  fields.note.value = '';
}

function setEditing(id) {
  editingId = id;
  if (id) {
    formTitle.textContent = '编辑投递记录';
    formMode.textContent = '正在编辑已有记录，保存后覆盖原内容';
    resetBtn.hidden = false;
  } else {
    formTitle.textContent = '新增投递记录';
    formMode.textContent = '正在新增一条记录';
    resetBtn.hidden = true;
  }
}

function renderStats(records) {
  const counts = { all: records.length };
  STAGES.forEach((s) => { counts[s] = 0; });
  records.forEach((r) => { counts[r.stage] = (counts[r.stage] || 0) + 1; });
  app.querySelectorAll('[data-stat-num]').forEach((node) => {
    const key = node.getAttribute('data-stat-num');
    node.textContent = String(counts[key] || 0);
  });
}

function renderFilters() {
  chipButtons.forEach((btn) => {
    const active = btn.getAttribute('data-filter') === filter;
    btn.classList.toggle('is-active', active);
    btn.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
}

function buildRecordItem(record) {
  const li = document.createElement('li');
  li.className = 'record';
  li.setAttribute('data-stage', record.stage);
  li.setAttribute('data-id', record.id);

  const top = document.createElement('div');
  top.className = 'record-top';

  const info = document.createElement('div');
  const company = document.createElement('p');
  company.className = 'record-company';
  company.textContent = record.company || '（未填写公司）';
  info.appendChild(company);
  if (record.position) {
    const pos = document.createElement('p');
    pos.className = 'record-position';
    pos.textContent = record.position;
    info.appendChild(pos);
  }

  const tag = document.createElement('span');
  tag.className = 'stage-tag';
  tag.setAttribute('data-stage', record.stage);
  tag.textContent = record.stage;

  top.appendChild(info);
  top.appendChild(tag);
  li.appendChild(top);

  const meta = document.createElement('p');
  meta.className = 'record-meta';
  meta.textContent = `投递日期：${record.date || '未填写'}`;
  li.appendChild(meta);

  if (record.note) {
    const note = document.createElement('p');
    note.className = 'record-note';
    note.textContent = record.note;
    li.appendChild(note);
  }

  const actions = document.createElement('div');
  actions.className = 'record-actions';

  const editBtn = document.createElement('button');
  editBtn.type = 'button';
  editBtn.className = 'btn btn-ghost btn-small';
  editBtn.setAttribute('data-action', 'edit');
  editBtn.textContent = '编辑';

  const delBtn = document.createElement('button');
  delBtn.type = 'button';
  delBtn.className = 'btn btn-ghost btn-small';
  delBtn.setAttribute('data-action', 'delete');
  delBtn.textContent = '删除';

  actions.appendChild(editBtn);
  actions.appendChild(delBtn);
  li.appendChild(actions);

  return li;
}

function renderList() {
  const records = state[STORE_KEY] || [];
  renderStats(records);
  renderFilters();

  const visible = filter === '全部' ? records : records.filter((r) => r.stage === filter);
  listEl.textContent = '';
  visible.forEach((r) => listEl.appendChild(buildRecordItem(r)));

  listCount.textContent = `${visible.length} 条`;
  emptyEl.hidden = visible.length > 0;
  if (visible.length === 0) {
    emptyEl.textContent = records.length === 0
      ? '暂无记录，先在上方添加一条吧。'
      : `当前筛选（${filter}）下没有记录。`;
  }
}

async function persist(nextRecords) {
  const next = { ...state, [STORE_KEY]: nextRecords };
  await appStore.setState(next);
  state = normalizeState(next);
}

async function handleSave() {
  clearError(formError);
  const data = readForm();
  if (!data.company) {
    showError(formError, '请填写公司名称。');
    fields.company.focus();
    return;
  }

  const records = (state[STORE_KEY] || []).slice();
  let next;
  if (editingId) {
    const idx = records.findIndex((r) => r.id === editingId);
    if (idx === -1) {
      showError(formError, '要编辑的记录已不存在，请重新选择。');
      setEditing(null);
      clearForm();
      return;
    }
    next = records.slice();
    next[idx] = { ...records[idx], ...data };
  } else {
    const record = { id: `rec-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, ...data };
    next = records.concat([record]);
  }

  try {
    await persist(next);
  } catch (err) {
    showError(formError, '保存失败，请重试。你的输入已保留。');
    return;
  }

  setEditing(null);
  clearForm();
  renderList();
}

function handleEdit(id) {
  const record = (state[STORE_KEY] || []).find((r) => r.id === id);
  if (!record) {
    showError(listError, '该记录已不存在。');
    return;
  }
  clearError(listError);
  clearError(formError);
  fillForm(record);
  setEditing(id);
  formTitle.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function askDelete(id) {
  const record = (state[STORE_KEY] || []).find((r) => r.id === id);
  if (!record) {
    showError(listError, '该记录已不存在。');
    return;
  }
  clearError(listError);
  pendingDeleteId = id;
  confirmText.textContent = `确定要删除「${record.company || '未填写公司'}${record.position ? ' · ' + record.position : ''}」这条投递记录吗？此操作不可撤销。`;
  confirmBox.hidden = false;
  confirmBox.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function closeConfirm() {
  pendingDeleteId = null;
  confirmBox.hidden = true;
  confirmText.textContent = '';
}

async function doDelete() {
  if (!pendingDeleteId) { closeConfirm(); return; }
  const id = pendingDeleteId;
  const next = (state[STORE_KEY] || []).filter((r) => r.id !== id);
  try {
    await persist(next);
  } catch (err) {
    showError(listError, '删除失败，请重试。');
    return;
  }
  if (editingId === id) {
    setEditing(null);
    clearForm();
  }
  closeConfirm();
  renderList();
}

function handleReset() {
  clearError(formError);
  setEditing(null);
  clearForm();
}

el('[data-action="save"]').addEventListener('click', () => { handleSave(); });
resetBtn.addEventListener('click', handleReset);
confirmDeleteBtn.addEventListener('click', () => { doDelete(); });
cancelDeleteBtn.addEventListener('click', closeConfirm);

chipButtons.forEach((btn) => {
  btn.addEventListener('click', () => {
    filter = btn.getAttribute('data-filter') || '全部';
    renderList();
  });
});

listEl.addEventListener('click', (event) => {
  const btn = event.target.closest('button[data-action]');
  if (!btn) return;
  const li = btn.closest('.record');
  if (!li) return;
  const id = li.getAttribute('data-id');
  const action = btn.getAttribute('data-action');
  if (action === 'edit') handleEdit(id);
  else if (action === 'delete') askDelete(id);
});

const raw = await appStore.getState();
state = normalizeState(raw);

if (!Array.isArray(state[STORE_KEY])) {
  state = { ...state, [STORE_KEY]: seedRecords().map(normalizeRecord) };
  try {
    await appStore.setState(state);
  } catch (err) {
    showError(listError, '初始化数据保存失败，当前仅在本页显示。');
  }
}

clearForm();
setEditing(null);
renderList();

