:root {
  --blue-700: #1d4ed8;
  --blue-600: #2563eb;
  --blue-500: #3b82f6;
  --blue-100: #dbeafe;
  --blue-50: #eff6ff;
  --ink: #0f172a;
  --ink-soft: #475569;
  --line: #e2e8f0;
  --bg: #f5f8ff;
  --white: #ffffff;
  --danger: #dc2626;
  --danger-soft: #fee2e2;
  --radius: 14px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  font-size: 15px;
  line-height: 1.5;
  -webkit-text-size-adjust: 100%;
}

.app-header {
  background: linear-gradient(135deg, var(--blue-600), var(--blue-500));
  color: #fff;
  padding: 22px 16px 26px;
  border-radius: 0 0 22px 22px;
}

.app-header h1 {
  margin: 0;
  font-size: 21px;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  opacity: 0.9;
}

.stats {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  padding: 14px 12px 4px;
  margin-top: -14px;
}

.stat-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 10px 4px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 2px;
  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.06);
}

.stat-num {
  font-size: 19px;
  font-weight: 700;
  color: var(--blue-700);
  line-height: 1.1;
}

.stat-label {
  font-size: 11px;
  color: var(--ink-soft);
  white-space: nowrap;
}

.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  margin: 14px 12px;
  padding: 16px 14px;
  box-shadow: 0 2px 10px rgba(15, 23, 42, 0.04);
}

.panel-title {
  margin: 0;
  font-size: 16px;
  color: var(--ink);
}

.form-hint {
  margin: 6px 0 12px;
  font-size: 12px;
  color: var(--blue-600);
  background: var(--blue-50);
  border-radius: 8px;
  padding: 6px 10px;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field label {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-soft);
}

.req { color: var(--danger); }

input[type="text"],
input[type="date"],
select,
textarea {
  width: 100%;
  font: inherit;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 11px 12px;
  min-height: 44px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

textarea { resize: vertical; min-height: 76px; }

input:focus,
select:focus,
textarea:focus {
  border-color: var(--blue-500);
  box-shadow: 0 0 0 3px var(--blue-100);
}

.form-actions {
  display: flex;
  gap: 10px;
  margin-top: 14px;
  flex-wrap: wrap;
}

.btn {
  font: inherit;
  font-weight: 600;
  border-radius: 10px;
  border: 1px solid transparent;
  padding: 11px 18px;
  min-height: 44px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.btn-primary {
  background: var(--blue-600);
  color: #fff;
  flex: 1 1 auto;
}

.btn-primary:hover { background: var(--blue-700); }

.btn-ghost {
  background: var(--white);
  color: var(--blue-700);
  border-color: var(--blue-100);
}

.btn-ghost:hover { background: var(--blue-50); }

.btn-danger {
  background: var(--danger);
  color: #fff;
  flex: 1 1 auto;
}

.btn-danger:hover { background: #b91c1c; }

.btn-small {
  padding: 8px 12px;
  min-height: 38px;
  font-size: 13px;
}

.error {
  margin: 10px 0 0;
  color: var(--danger);
  background: var(--danger-soft);
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 13px;
}

.list-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.count-badge {
  font-size: 12px;
  color: var(--blue-700);
  background: var(--blue-50);
  border-radius: 999px;
  padding: 3px 10px;
  white-space: nowrap;
}

.filters {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding: 12px 0 4px;
  -webkit-overflow-scrolling: touch;
}

.chip {
  font: inherit;
  font-size: 13px;
  white-space: nowrap;
  border: 1px solid var(--blue-100);
  background: var(--white);
  color: var(--blue-700);
  border-radius: 999px;
  padding: 8px 14px;
  min-height: 38px;
  cursor: pointer;
}

.chip.is-active {
  background: var(--blue-600);
  border-color: var(--blue-600);
  color: #fff;
}

.record-list {
  list-style: none;
  margin: 10px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.record {
  border: 1px solid var(--line);
  border-left: 4px solid var(--blue-500);
  border-radius: 12px;
  padding: 12px;
  background: var(--white);
}

.record[data-stage="待投递"] { border-left-color: #94a3b8; }
.record[data-stage="已投递"] { border-left-color: var(--blue-500); }
.record[data-stage="面试中"] { border-left-color: #f59e0b; }
.record[data-stage="已结束"] { border-left-color: #64748b; }

.record-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.record-company {
  font-size: 15px;
  font-weight: 700;
  margin: 0;
  word-break: break-word;
}

.record-position {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
  word-break: break-word;
}

.stage-tag {
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 600;
  border-radius: 999px;
  padding: 4px 10px;
  background: var(--blue-50);
  color: var(--blue-700);
  white-space: nowrap;
}

.stage-tag[data-stage="待投递"] { background: #f1f5f9; color: #475569; }
.stage-tag[data-stage="已投递"] { background: var(--blue-50); color: var(--blue-700); }
.stage-tag[data-stage="面试中"] { background: #fef3c7; color: #b45309; }
.stage-tag[data-stage="已结束"] { background: #e2e8f0; color: #475569; }

.record-meta {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--ink-soft);
}

.record-note {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--ink);
  background: var(--blue-50);
  border-radius: 8px;
  padding: 8px 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.empty {
  margin: 14px 0 4px;
  text-align: center;
  color: var(--ink-soft);
  font-size: 13px;
  padding: 18px 10px;
  border: 1px dashed var(--line);
  border-radius: 12px;
}

.danger-zone { border-color: #fecaca; }

.confirm-text {
  margin: 8px 0 0;
  font-size: 14px;
  color: var(--ink);
  word-break: break-word;
}

@media (min-width: 560px) {
  .form-grid { grid-template-columns: 1fr 1fr; }
  .field-full { grid-column: 1 / -1; }
  .panel { margin: 16px auto; max-width: 720px; }
  .stats { max-width: 720px; margin-left: auto; margin-right: auto; }
  .app-header { padding-left: 24px; padding-right: 24px; }
}
